    "some soup": "немного супа",
    "some wine, a glass of": "немного вина, бокал",
    "{Leib} is the dark rye bread Estonians eat every day. White bread is {sai}, from lesson 24.": "{Leib} это тёмный ржаной хлеб, который эстонцы едят каждый день. Белый хлеб это {sai}, из урока 24.",
    "{Toit} is food in general, the word on a menu or a shop sign.": "{Toit} это еда вообще, слово из меню или с вывески магазина.",
    "Say what you eat.": "Скажи, что ты ешь.",
    "Say you'd like bread and cheese.": "Скажи, что тебе хотелось бы хлеба и сыра.",
    "I'd like bread and cheese.": "Мне хотелось бы хлеба и сыра.",
    "Offer somebody soup.": "Предложи кому-нибудь суп.",
    "Do you want some soup?": "Хочешь супа?",
    "Excuse me, how much is this?": "Извините, сколько это стоит?",
    "Three euros.": "Три евро.",
    "And the cake?": "А торт?",
    "The cake is four euros fifty.": "Торт стоит четыре евро пятьдесят.",
    "Fine. One cake and one coffee, please.": "Хорошо. Один торт и один кофе, пожалуйста.",
    "Seven fifty altogether. By card?": "Всего семь пятьдесят. Картой?",
    "Yes, by card.": "Да, картой.",
    "How much does it cost?": "Сколько это стоит?",
    "to cost, to pay": "стоить, платить",
    "euro": "евро",
    "euros, after a number": "евро, после числа",
    "cent": "цент",
    "cents, after a number": "цента, после числа",
    "altogether, in total": "всего, в сумме",
    "by card": "картой",
    "in cash": "наличными",
    "One euro is {üks euro}. From two up it's {eurot}, so listen for the number first.": "«Один евро» по-эстонски {üks euro}. Начиная с двух, говорят {eurot}, так что сначала слушай число.",
    "People often drop the cents word: {neli eurot viiskümmend}.": "Центы часто не называют: {neli eurot viiskümmend}.",
    "Price": "Цена",
    "Ask how much something costs.": "Спроси, сколько что-то стоит.",
    "Say yes, by card.": "Скажи: да, картой.",
    "Five euros altogether. By card?": "Всего пять евро. Картой?",
    "Say no, you'll pay cash.": "Скажи, что нет, заплатишь наличными.",
    "By card?": "Картой?",
    "No, cash.": "Нет, наличными.",
    "Tom, do you like coffee?": "Том, тебе нравится кофе?",
    "Yes, I like coffee a lot. And you?": "Да, мне очень нравится кофе. А тебе?",
    "I don't like coffee. I like tea.": "Мне не нравится кофе. Мне нравится чай.",
    "And Jaan? Does he like tea?": "А Яан? Ему нравится чай?",
    "No. He only likes beer!": "Нет. Ему нравится только пиво!",
    "to you": "тебе",
    "to him, to her": "ему, ей",
    "to us": "нам",
    "to you, polite or more than one": "вам, вежливо или нескольким людям",
    "to them": "им",
    "only": "только",
    "beer": "пиво",
    "Likes it": "Нравится",
    "Doesn't": "Не нравится",
    "Do you like coffee?": "Тебе нравится кофе?",
    "Yes, I like coffee.": "Да, мне нравится кофе.",
    "Say you don't like beer.": "Скажи, что тебе не нравится пиво.",
    "I don't like beer.": "Мне не нравится пиво.",
    "Ask a friend whether they like tea.": "Спроси друга, нравится ли ему чай.",
    "Do you like tea?": "Тебе нравится чай?",
    "Good evening! What would you like?": "Добрый вечер! Что желаете?",
    "Hello! A coffee and a tea, please.": "Здравствуйте! Кофе и чай, пожалуйста.",
    "Yes, two cakes. I love cake!": "Да, два пирожных. Я обожаю пирожные!",
    "Two cakes. Here you are!": "Два пирожных. Пожалуйста!",
    "Excuse me, how much is it?": "Извините, сколько это стоит?",
    "Later.": "Потом.",
    "Nine euros altogether.": "Всего девять евро.",
    "A whole evening at a café, made only of what this part taught.": "Целый вечер в кафе, только из того, чему научила эта часть.",
    "If the price comes too fast, you already have the line for it: {Aeglasemalt, palun}.": "Если цену назовут слишком быстро, у тебя уже есть нужная фраза: {Aeglasemalt, palun}.",
    "Notice how little you need: what you want, how many, and how you'll pay.": "Заметь, как мало нужно: что ты хочешь, сколько и как будешь платить.",
    "Mari's {kaks kooki} and her {Mulle meeldib kook} show both rules of this part: a number takes the {osastav}, and the thing you like stays plain.": "{kaks kooki} и {Mulle meeldib kook} у Мари показывают оба правила этой части. Число требует {osastav}, а то, что нравится, остаётся в простой форме.",
    "Order a coffee and a cake.": "Закажи кофе и пирожное.",
    "A coffee and a cake, please.": "Кофе и пирожное, пожалуйста.",
    "Say you'll pay by card.": "Скажи, что заплатишь картой.",
    "Six euros altogether.": "Всего шесть евро.",
    "Say you like tea, but not coffee.": "Скажи, что тебе нравится чай, но не кофе.",
    "I like tea, but not coffee.": "Мне нравится чай, но не кофе.",
    "Ask for a glass of water too.": "Попроси ещё и стакан воды.",
    "Yes, a glass of water too.": "Да, и стакан воды тоже.",
    "Ask how much it is.": "Спроси, сколько это стоит.",
    "Here you are!": "Пожалуйста!",
    "Thanks! How much is it?": "Спасибо! Сколько это стоит?",
    "You're at a café counter with a friend. The waiter, Liis, speaks first.": "Ты с другом у стойки в кафе. Первой говорит официантка Лийс.",
    "And where's the kitchen?": "А где кухня?",
    "The kitchen's here. And my room's over there.": "Кухня здесь. А моя комната вон там.",
    "This is a table and this is a chair. And that's the bed.": "Это стол, а это стул. А вон там кровать.",
    "And where's the window?": "А где окно?",
    "The window? Here!": "Окно? Здесь!",
    "home": "дом",
    "house": "дом, здание",
    "room": "комната",
    "bed": "кровать",
    "{Tuba} is a room you live in. The kitchen is never a {tuba}, it's {köök}.": "{Tuba} это комната, в которой живут. Кухня никогда не {tuba}, это {köök}.",
    "{Siin} is here, near you, and {seal} is there, further off. Point as you say it.": "{Siin} значит «здесь», рядом с тобой, а {seal} «там», подальше. Показывай рукой, когда говоришь.",
    "a room": "комната",
