    "a door": "дверь",
    "Say it's here.": "Скажи, что это здесь.",
    "Where's the kitchen?": "Где кухня?",
    "The kitchen's here.": "Кухня здесь.",
    "It's a table. Say so.": "Это стол. Так и скажи.",
    "It's a table.": "Это стол.",
    "Tom, where are you?": "Том, ты где?",
    "I'm at home. And you?": "Я дома. А ты?",
    "I'm still at work.": "Я ещё на работе.",
    "And where are you going after that?": "А куда ты пойдёшь потом?",
    "From work I'm going to the shop, and then home.": "С работы я иду в магазин, а потом домой.",
    "I'm coming to the shop too! See you in the shop, then!": "Я тоже иду в магазин! Тогда увидимся в магазине!",
    "where to": "куда",
    "where from": "откуда",
    "then, after that": "потом, после этого",
    "work, a job": "работа",
