    "from work": "с работы",
    "in the shop": "в магазине",
    "to the shop": "в магазин",
    "from the shop": "из магазина",
    "Estonian asks about a place three ways, and every place answers all three.": "В эстонском о месте спрашивают тремя способами, и у каждого места есть все три ответа.",
    "{Koju} and {poodi} are where to, never where. {Ma olen kodus}, but {Ma lähen koju}.": "{Koju} и {poodi} отвечают на «куда», а не на «где». {Ma olen kodus}, но {Ma lähen koju}.",
    "One question for being somewhere, one for going there, one for coming from there. Estonian's place endings are built on this.": "Один вопрос о том, где ты находишься, другой о том, куда идёшь, третий о том, откуда. На этом построены эстонские окончания места.",
    "Learn each place as its set of three, and say them aloud together: {kodus, koju, kodust}.": "Учи каждое место тройкой и произноси все три вслух вместе: {kodus, koju, kodust}.",
    "{kus?} where": "{kus?} где",
    "{kuhu?} where to": "{kuhu?} куда",
    "{kust?} where from": "{kust?} откуда",
    "Say you're at home.": "Скажи, что ты дома.",
    "Where are you?": "Где ты?",
    "I'm at home.": "Я дома.",
    "Say you're going to the shop.": "Скажи, что идёшь в магазин.",
    "Where are you going?": "Куда ты идёшь?",
    "I'm going to the shop.": "Я иду в магазин.",
    "Say you're coming from work.": "Скажи, что идёшь с работы.",
    "Where are you coming from?": "Откуда ты идёшь?",
    "I'm coming from work.": "Я иду с работы.",
    "Say you're going to work and then home.": "Скажи, что идёшь на работу, а потом домой.",
    "I'm going to work and then home.": "Я иду на работу, а потом домой.",
    "Mari, where's my phone?": "Мари, где мой телефон?",
    "In the kitchen?": "На кухне?",
    "No, it's not in the kitchen.": "Нет, на кухне его нет.",
    "In the room? In bed?": "В комнате? В кровати?",
    "Yes! In bed! Thanks!": "Да! В кровати! Спасибо!",
