    "Where's the phone?": "Где телефон?",
    "In the kitchen.": "На кухне.",
    "Say you're in your room.": "Скажи, что ты в своей комнате.",
    "I'm in my room.": "Я в своей комнате.",
    "And where do you sleep?": "А где ты спишь?",
    "In the bedroom. The bedroom's there.": "В спальне. Спальня там.",
    "Where's the bathroom?": "Где ванная?",
    "The bathroom's here.": "Ванная здесь.",
    "And the fridge?": "А холодильник?",
    "In the kitchen, of course! There's juice in the fridge.": "На кухне, конечно! В холодильнике есть сок.",
