    "Yes?": "Да?",
    "Ask whether it's far.": "Спроси, далеко ли это.",
    "You're in town and need the pharmacy. Stop somebody and ask. They answer first in Estonian.": "Ты в городе, и тебе нужна аптека. Останови кого-нибудь и спроси. Сначала тебе отвечают по-эстонски.",
    "No, it's small. But it's nice.": "Нет, маленькая. Но хорошая.",
    "And the kitchen?": "А кухня?",
