    "Most of these come in pairs, so learn them as pairs and say them aloud together: {suur, väike}.": "Большинство из них идут парами, так что учи их парами и произноси вслух вместе: {suur, väike}.",
    "And its opposite": "И его противоположность",
    "Say no, it's small, but nice.": "Скажи: нет, маленькая, но хорошая.",
    "No, it's small, but nice.": "Нет, маленькая, но хорошая.",
    "Say the coffee here is expensive.": "Скажи, что кофе здесь дорогой.",
    "The coffee here is expensive.": "Кофе здесь дорогой.",
    "Say no, it's old.": "Скажи: нет, он старый.",
    "No, it's old.": "Нет, он старый.",
