    "young": "молодой",
    "lesson; hour": "урок; час",
    "Describing words come in pairs, so learn them as opposites, as in lesson 36: {pikk} and {lühike}.": "Описательные слова идут парами, поэтому учи их как противоположности, как в уроке 36: {pikk} и {lühike}.",
    "{Lihtne} and {kerge} both mean easy. {Lihtne} is simple to do; {kerge} is also light to carry.": "{Lihtne} и {kerge} оба значат «лёгкий». {Lihtne} значит «простой в исполнении»; {kerge} ещё и «лёгкий по весу».",
    "The opposite": "Противоположность",
    "Say it's a little hard, but beautiful.": "Скажи, что он немного трудный, но красивый.",
    "Is Estonian hard?": "Эстонский трудный?",
    "Say it's interesting.": "Скажи, что она интересная.",
    "How's your job?": "Как твоя работа?",
    "Interesting!": "Интересная!",
    "Say you're in a hurry.": "Скажи, что ты спешишь.",
    "I'm in a hurry.": "Я спешу.",
    "Tom, what color is your phone?": "Том, какого цвета твой телефон?",
    "Black. And yours?": "Чёрного. А твой?",
    "My phone's red. I love red!": "Мой телефон красный. Я люблю красный!",
    "I like blue. And green.": "Мне нравится синий. И зелёный.",
    "And what color is your kitchen?": "А какого цвета твоя кухня?",
    "White and yellow.": "Белая и жёлтая.",
    "What color?": "Какого цвета?",
    "color": "цвет",
    "yellow": "жёлтый",
    "Ask {Mis värvi?} and answer with the color, as it is: {Must}.": "Спроси {Mis värvi?} и ответь названием цвета без изменений: {Must}.",
    "Four of the colors end the same way: {punane}, {sinine}, {roheline}, {kollane}. Say them aloud as a list.": "Четыре цвета кончаются одинаково: {punane}, {sinine}, {roheline}, {kollane}. Произнеси их вслух подряд.",
    "Say what color yours is.": "Скажи, какого цвета твой.",
    "What color is your phone?": "Какого цвета твой телефон?",
    "Black.": "Чёрного.",
    "Say you like green.": "Скажи, что тебе нравится зелёный.",
    "I like green.": "Мне нравится зелёный.",
    "Ask what color something is.": "Спроси, какого цвета что-нибудь.",
    "What color is it?": "Какого это цвета?",
    "Hello! I need a jacket.": "Здравствуйте! Мне нужна куртка.",
    "Black or blue.": "Чёрная или синяя.",
