    "How much is the black jacket?": "Сколько стоит чёрная куртка?",
    "Fifty euros.": "Пятьдесят евро.",
    "Fine. And I need a hat too.": "Хорошо. И ещё мне нужна шапка.",
    "needed (as in “I need it”)": "нужно (как в «мне нужно»)",
