    "What size?": "Какой размер?",
    "Small, please.": "Маленький, пожалуйста.",
    "Here's a gray coat, in small. And this scarf is gray too.": "Вот серое пальто, маленького размера. И этот шарф тоже серый.",
    "Very nice! But I need a sweater too.": "Очень красиво! Но мне нужен ещё и свитер.",
