    "a Latvian": "латиш",
    "a German": "німець",
    "{Saksamaa} is a -maa country, like {Inglismaa}: from Germany is {Saksamaalt}, never with -st.": "{Saksamaa} належить до країн на -maa, як і {Inglismaa}: «з Німеччини» буде {Saksamaalt}, ніколи не з -st.",
    "Say you're from Finland, or where you're really from.": "Скажи, що ти з Фінляндії, або звідки ти насправді.",
    "I'm from Finland.": "Я з Фінляндії.",
    "Say a friend of yours lives in Sweden.": "Скажи, що твій друг живе у Швеції.",
    "My friend lives in Sweden.": "Мій друг живе у Швеції.",
    "Say you're from Germany and you're German.": "Скажи, що ти з Німеччини й що ти німець.",
    "I'm from Germany. I'm German.": "Я з Німеччини. Я німець.",
    "Do you speak Estonian?": "Ти розмовляєш естонською?",
    "A little. I'm learning Estonian.": "Трохи. Я вчу естонську.",
    "Very good!": "Дуже добре!",
    "I speak English. And a little Estonian!": "Я розмовляю англійською. І трохи естонською!",
    "Let's speak Estonian!": "Давай розмовляти естонською!",
    "to speak": "говорити",
    "I speak": "я говорю",
    "you speak, one person you know": "ти говориш, звертання до одного знайомого",
    "he, she speaks": "він, вона говорить",
    "we speak, and let's speak": "ми говоримо, і давайте говорити",
    "you speak, polite or more than one": "ви говорите, ввічливо або до кількох",
    "they speak": "вони говорять",
    "to learn, to study": "вчити, вчитися",
    "I learn": "я вчу",
