    "he, she learns": "він, вона вчить",
    "we learn": "ми вчимо",
    "you learn, polite or more than one": "ви вчите, ввічливо або до кількох",
    "they learn": "вони вчать",
    "Estonian, the language": "естонська, мова",
    "English, the language": "англійська, мова",
    "Ukrainian, the language": "українська, мова",
    "{rääkima}, to speak": "{rääkima}, говорити",
    "{õppima}, to learn": "{õppima}, вчити",
    "Say a little, and that you're learning it.": "Скажи «трохи» і що ти її вчиш.",
    "Say which languages you speak.": "Скажи, якими мовами ти розмовляєш.",
    "I speak English and a little Estonian.": "Я розмовляю англійською й трохи естонською.",
    "Tom, do you live in Tallinn?": "Томе, ти живеш у Таллінні?",
    "No, I don't live in Tallinn. I live in Tartu.": "Ні, я не живу в Таллінні. Я живу в Тарту.",
    "A little. I don't speak it well yet.": "Трохи. Я ще не дуже добре розмовляю.",
    "But you're learning!": "Але ж ти вчиш!",
    "Yes, of course!": "Так, звісно!",
    "live, after {ei}": "жити, після {ei}",
    "speak, after {ei}": "говорити, після {ei}",
    "learn, after {ei}": "вчити, після {ei}",
    "yet, still": "ще, досі",
    "of course": "звісно",
    "You've been doing this since lesson 6, where {olen} became {ei ole}.": "Ти робиш це ще з уроку 6, де {olen} стало {ei ole}.",
    "Say no, you don't live in Tallinn. You live in Tartu.": "Скажи, що ні, ти не живеш у Таллінні. Ти живеш у Тарту.",
    "Do you live in Tallinn?": "Ти живеш у Таллінні?",
    "Say no, you don't.": "Скажи, що ні.",
    "Say you don't speak Estonian well yet.": "Скажи, що ти ще не дуже добре розмовляєш естонською.",
    "I don't speak Estonian well yet.": "Я ще не дуже добре розмовляю естонською.",
    "Say yes, of course.": "Скажи «так, звісно».",
    "Are you learning Estonian?": "Ти вчиш естонську?",
    "Tom, what's your phone number?": "Томе, який у тебе номер телефону?",
    "Five, two, zero, one, three, seven, eight.": "П'ять, два, нуль, один, три, сім, вісім.",
    "Slower, please!": "Повільніше, будь ласка!",
    "Five. Two. Zero. One. Three. Seven. Eight.": "П'ять. Два. Нуль. Один. Три. Сім. Вісім.",
    "Thanks! Mine is five, four, nine, six, zero, one, two.": "Дякую! Мій: п'ять, чотири, дев'ять, шість, нуль, один, два.",
    "zero, 0": "нуль, 0",
    "one, 1": "один, 1",
    "two, 2": "два, 2",
    "three, 3": "три, 3",
    "four, 4": "чотири, 4",
    "five, 5": "п'ять, 5",
    "six, 6": "шість, 6",
    "seven, 7": "сім, 7",
    "eight, 8": "вісім, 8",
    "nine, 9": "дев'ять, 9",
    "ten, 10": "десять, 10",
    "number": "номер",
    "phone number": "номер телефону",
    "Ten words, and a phone number is said one digit at a time.": "Десять слів, а номер телефону називають по одній цифрі.",
    "{Kuus}, six, has a long uu. Hold it, or it turns into another word.": "У {Kuus} (шість) довге uu. Тягни його, інакше вийде інше слово.",
    "{Telefoninumber} is {telefon} and {number} written as one word. Estonian builds long words by putting short ones together, and you'll see it everywhere.": "{Telefoninumber} складається з {telefon} і {number}, написаних одним словом. Естонська будує довгі слова з коротких, і ти побачиш це всюди.",
    "{Kaheksa} and {üheksa} are eight and nine, and they sound alike. Listen to the first sound.": "{Kaheksa} і {üheksa}: вісім і дев'ять, і звучать вони схоже. Слухай перший звук.",
    "{Mis su telefoninumber on?} is built just like {Mis su nimi on?}": "{Mis su telefoninumber on?} будується так само, як {Mis su nimi on?}",
    "Number": "Число",
    "Say a phone number, one digit at a time. Any one will do.": "Назви номер телефону по одній цифрі. Підійде будь-який.",
    "What's your phone number?": "Який у тебе номер телефону?",
    "Count from one to ten.": "Порахуй від одного до десяти.",
    "One, two, three, four, five, six, seven, eight, nine, ten.": "Один, два, три, чотири, п'ять, шість, сім, вісім, дев'ять, десять.",
    "Ask somebody for their phone number.": "Запитай у когось номер телефону.",
    "Tom, how old are you?": "Томе, скільки тобі років?",
    "I'm thirty-two years old. And you?": "Мені тридцять два роки. А тобі?",
    "Twenty-five.": "Двадцять п'ять.",
    "And Jaan?": "А Яану?",
    "Jaan's forty. He's old!": "Яану сорок. Він старий!",
    "I am not!": "Зовсім ні!",
    "From across the room.": "З іншого кінця кімнати.",
    "eleven, 11": "одинадцять, 11",
    "twelve, 12": "дванадцять, 12",
    "thirteen, 13": "тринадцять, 13",
