    "previous, the one before": "попередній",
    "last, final": "останній",
    "Say it was really funny.": "Скажи, що було дуже смішно.",
    "Really funny!": "Дуже смішно!",
    "Say that's right.": "Скажи, що це правильно.",
    "Say you're sure.": "Скажи, що ти впевнений (впевнена).",
    "I'm sure.": "Я певен.",
